<template>
  <div>
    <header v-if="!embedded" class="collection-detail-head">
      <div>
        <span class="collection-detail-kicker">{{ entry.category }} · {{ entry.period }}</span>
        <h3>{{ entry.title }}</h3>
        <p v-if="entry.subtitle" class="collection-detail-subtitle">{{ entry.subtitle }}</p>
      </div>
      <button type="button" class="collection-detail-close" aria-label="Close details" @click="$emit('close')">×</button>
    </header>
    <p v-if="embedded && showSubtitle && entry.subtitle" class="collection-detail-embedded-subtitle">{{ entry.subtitle }}</p>
    <div v-if="entry.lab" class="collection-detail-lab">
      <span>Associated with <a :href="entry.lab.url" target="_blank" rel="noopener"><b>{{ entry.lab.name }}</b></a></span>
      <span v-if="entry.lab.logo" class="collection-detail-logo">
        <img :src="entry.lab.logo" :style="{ height: entry.lab.logoHeight || '4rem' }" :alt="entry.lab.name">
      </span>
    </div>
    <div class="collection-detail-body" v-html="entry.body"></div>
    <div
      v-if="entry.images && entry.images.length"
      class="scroll-container project proof-gallery collection-detail-gallery"
      :class="entry.galleryClass"
    >
      <img
        v-for="(image, index) in entry.images"
        :key="`${image.fullSrc}-${index}`"
        :src="image.src"
        :data-full-src="image.fullSrc"
        :alt="image.alt"
        loading="lazy"
        decoding="async"
      >
    </div>
    <PublicationMeta v-if="entry.kind === 'research' && entry.publication && entry.publication.citation !== false" :pub="entry.publication" :search-terms="[]" />
    <footer v-if="entry.kind !== 'research' && (entry.status || entry.route || (entry.links && entry.links.length) || (entry.extraLinks && entry.extraLinks.length))" class="collection-detail-footer">
      <span v-if="entry.status && entry.kind !== 'research'" class="collection-detail-status">{{ entry.status }}</span>
      <a v-if="entry.route && entry.externalPage" class="collection-project-link" :href="entry.route" target="_blank" rel="noopener"><span>{{ entry.action || 'Open project' }}</span><span class="collection-project-arrow" aria-hidden="true"><ArrowUpRightIcon /></span></a>
      <router-link v-else-if="entry.route" class="collection-project-link" :to="entry.route">
        <span>{{ entry.action || 'Open project' }}</span>
        <span class="collection-project-arrow" aria-hidden="true"><SiteIcon name="arrow-right" /></span>
      </router-link>
      <GitHubRepoLink
        v-for="link in entry.extraLinks || []"
        :key="link.url"
        :href="link.url"
        :label="link.label"
        :icon-class="link.iconClass || 'fab fa-github'"
      />
    </footer>
    <SourceViewLinks v-if="entry.sourceId" :source-id="entry.sourceId" />
  </div>
</template>

<script>
import PublicationMeta from '../PublicationMeta.vue';
import SourceViewLinks from './SourceViewLinks.vue';
import GitHubRepoLink from './GitHubRepoLink.vue';

export default {
  name: 'CollectionDetail',
  components: { PublicationMeta, SourceViewLinks, GitHubRepoLink },
  props: {
    entry: {
      type: Object,
      required: true
    },
    embedded: {
      type: Boolean,
      default: false
    },
    showSubtitle: {
      type: Boolean,
      default: false
    }
  },
  emits: ['close']
};
</script>
